def evaluate(instance):
    # Extract final text response
    response_text = ""
    response_obj = instance.get("response") or {}
    if isinstance(response_obj, dict):
        parts = response_obj.get("parts", [])
        if parts and isinstance(parts, list):
            response_text = parts[0].get("text", "")
    elif isinstance(response_obj, str):
        response_text = response_obj

    text_lower = response_text.lower()

    # Refusal cases do not require policy citations
    refusal_markers = ["cannot", "not in the handbook", "no policy on file", "decline", "out of domain", "unable to assist"]
    if any(m in text_lower for m in refusal_markers):
        return {"score": 1.0, "explanation": "Valid refusal detected; citation not required."}

    # Policy responses must cite specific section or source
    has_source = "source" in text_lower or "section " in text_lower or "sec. " in text_lower
    if has_source:
        return {"score": 1.0, "explanation": "Valid source citation detected in response."}
    else:
        return {"score": 0.0, "explanation": "Missing required policy source citation (Sources: Section ...)."}
